# Review package: af34735..8737f76

## Commits
8737f76 Fix empty-string option handling and add missing trim test

## Files changed
 greet.js      | 4 ++--
 greet.test.js | 8 ++++++++
 2 files changed, 10 insertions(+), 2 deletions(-)

## Diff
diff --git a/greet.js b/greet.js
index 3f4fa89..d80ccf2 100644
--- a/greet.js
+++ b/greet.js
@@ -1,11 +1,11 @@
 function greet(name, options = {}) {
-  const greeting = options.greeting || 'Hello';
-  const punctuation = options.punctuation || '!';
+  const greeting = options.greeting ?? 'Hello';
+  const punctuation = options.punctuation ?? '!';

   // Handle empty, undefined, or whitespace-only input
   const effectiveName = (name && name.trim()) ? name.trim() : 'there';

   return `${greeting}, ${effectiveName}${punctuation}`;
 }

 module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
index e591b78..21071bf 100644
--- a/greet.test.js
+++ b/greet.test.js
@@ -28,10 +28,18 @@ test('greet accepts custom greeting word', () => {

 test('greet accepts custom punctuation', () => {
   const result = greet('Alice', { punctuation: '.' });
   assert.strictEqual(result, 'Hello, Alice.');
 });

 test('greet accepts both custom greeting and punctuation', () => {
   const result = greet('Alice', { greeting: 'Hey', punctuation: '!!' });
   assert.strictEqual(result, 'Hey, Alice!!');
 });
+
+test('greet accepts empty string punctuation', () => {
+  assert.strictEqual(greet('Alice', { punctuation: '' }), 'Hello, Alice');
+});
+
+test('greet trims surrounding whitespace from a name', () => {
+  assert.strictEqual(greet('  Alice  '), 'Hello, Alice!');
+});
